/* SPAN3: the ledger has no language column and the hourly rebuild owns its
   layout, so a Spanish guest's language is kept in Script Properties instead.
   Only "es" is stored; no entry means English, which also covers OTA guests and
   every booking made before this. An English booking clears an earlier entry.
   Never starts with "booking_": the poll reads that prefix. Failure here must
   not block a paid booking. */
function rememberGuestLang_(data) {
  try {
    var email = String(data.email || "").trim().toLowerCase();
    if (!email) return;
    var props = PropertiesService.getScriptProperties();
    if (bookingLang_(data.lang) === "es") props.setProperty(GUEST_LANG_PREFIX + email, "es");
    else props.deleteProperty(GUEST_LANG_PREFIX + email);
  } catch (err) {
    Logger.log("rememberGuestLang_ skipped: " + err.message);
  }
}

